import {clamp} from './geometry.8135d600ec1c.mjs';
export function setupGallery({project,language,onOpen,onClose}){
 const t=(tr,en)=>language==='en'?en:tr,abort=new AbortController(),opts={signal:abort.signal};
 const dialog=document.createElement('dialog');dialog.className='art-viewer';dialog.setAttribute('aria-label',t('Görsel inceleyici','Image viewer'));document.body.append(dialog);
 dialog.innerHTML=`<div class="viewer-shell"><header class="gallery-toolbar"><h2></h2><button class="gallery-prev" aria-label="${t('Önceki görsel','Previous image')}">←</button><button class="gallery-next" aria-label="${t('Sonraki görsel','Next image')}">→</button><button class="gallery-out" aria-label="${t('Uzaklaştır','Zoom out')}">−</button><button class="gallery-in" aria-label="${t('Yakınlaştır','Zoom in')}">+</button><button class="gallery-fit">${t('Sığdır','Fit')}</button><a class="gallery-original" target="_blank" rel="noopener">${t('Orijinal','Original')} ↗</a><button class="gallery-close" aria-label="${t('Görsel inceleyiciyi kapat','Close image viewer')}">✕</button></header><div class="gallery-stage" tabindex="0" aria-label="${t('Yakınlaştırılmış görseli sürükleyin veya ok tuşlarıyla hareket ettirin','Drag the zoomed image or move it with arrow keys')}"><img class="gallery-image" draggable="false" alt=""><p class="gallery-error" hidden>${t('Görsel yüklenemedi. Orijinal bağlantısını deneyin.','The image could not load. Try the original link.')}</p></div><div class="gallery-caption"><span class="gallery-position" role="status" aria-live="polite"></span><span class="gallery-help">${t('+/− Yakınlaştır · Oklar: gezin / taşı · Esc: kapat','+/− Zoom · Arrows: browse / pan · Esc: close')}</span></div><div class="gallery-thumbs"></div></div>`;
 const q=s=>dialog.querySelector(s),stage=q('.gallery-stage'),img=q('.gallery-image');let slides=[],index=0,zoom=1,x=0,y=0,opener,drag;
 const on=(el,event,fn)=>el.addEventListener(event,fn,opts);
 const paint=()=>{const bx=stage.clientWidth*(zoom-1)/2,by=stage.clientHeight*(zoom-1)/2;x=clamp(x,-bx,bx);y=clamp(y,-by,by);img.style.transform=`translate(${x}px,${y}px) scale(${zoom})`;q('.gallery-fit').textContent=`${t('Sığdır','Fit')} · ${Math.round(zoom*100)}%`;};
 const fit=()=>{zoom=1;x=y=0;paint();};
 const show=i=>{index=clamp(i,0,slides.length-1);const s=slides[index];img.src=s.src;img.alt=s.label;q('.gallery-original').href=s.src;q('.gallery-position').textContent=`${index+1} / ${slides.length} — ${s.label}`;q('.gallery-prev').disabled=index===0;q('.gallery-next').disabled=index===slides.length-1;q('.gallery-error').hidden=true;q('.gallery-thumbs').querySelectorAll('button').forEach((b,n)=>b.setAttribute('aria-current',String(n===index)));fit();};
 const open=(items,start,trigger)=>{slides=items;opener=trigger;q('h2').textContent=project?project.title[language==='en'?1:0]:t('Eskiz defterinden','From the sketchbook');q('.gallery-thumbs').replaceChildren();slides.forEach((s,i)=>{const b=document.createElement('button');b.setAttribute('aria-label',s.label);const thumb=document.createElement('img');thumb.src=s.src;thumb.alt='';b.append(thumb);b.addEventListener('click',()=>show(i));q('.gallery-thumbs').append(b);});dialog.showModal();document.body.classList.add('viewer-active');onOpen?.();show(start);q('.gallery-close').focus();};
 const close=()=>{if(!dialog.open)return;dialog.close();document.body.classList.remove('viewer-active');onClose?.();opener?.focus({preventScroll:true});};
 on(q('.gallery-close'),'click',close);on(dialog,'cancel',e=>{e.preventDefault();close();});on(q('.gallery-prev'),'click',()=>show(index-1));on(q('.gallery-next'),'click',()=>show(index+1));on(q('.gallery-in'),'click',()=>{zoom=clamp(zoom+.5,1,4);paint();});on(q('.gallery-out'),'click',()=>{zoom=clamp(zoom-.5,1,4);paint();});on(q('.gallery-fit'),'click',fit);
 on(stage,'wheel',e=>{e.preventDefault();zoom=clamp(zoom+(e.deltaY<0?.15:-.15),1,4);paint();});
 on(stage,'pointerdown',e=>{if(e.button>0)return;drag={id:e.pointerId,x:e.clientX-x,y:e.clientY-y};stage.setPointerCapture(e.pointerId);});on(stage,'pointermove',e=>{if(drag?.id!==e.pointerId)return;x=e.clientX-drag.x;y=e.clientY-drag.y;paint();});on(stage,'pointerup',()=>drag=null);on(stage,'pointercancel',()=>drag=null);on(stage,'lostpointercapture',()=>drag=null);
 on(dialog,'keydown',e=>{if(e.key==='+'||e.key==='='){e.preventDefault();zoom=clamp(zoom+.5,1,4);paint();}else if(e.key==='-'){e.preventDefault();zoom=clamp(zoom-.5,1,4);paint();}else if(e.key.startsWith('Arrow')){e.preventDefault();if(zoom===1){if(e.key==='ArrowRight')show(index+1);if(e.key==='ArrowLeft')show(index-1);}else{x+=e.key==='ArrowLeft'?40:e.key==='ArrowRight'?-40:0;y+=e.key==='ArrowUp'?40:e.key==='ArrowDown'?-40:0;paint();}}});on(img,'error',()=>q('.gallery-error').hidden=false);on(window,'resize',paint);
 if(project){const items=[{src:'../../'+project.puzzleImage,label:t('Çizim','Drawing')},{src:'../../'+project.image,label:t('Görselleştirme','Visualization')},...project.pages.map((n,i)=>({src:`../../assets/boards/page-${n}.webp`,label:`${t('Pafta','Board')} ${i+1}`}))];
 const bind=(el,index)=>{el.classList.add('viewer-trigger');if(el.tagName!=='A'){el.tabIndex=0;el.setAttribute('role','button');el.setAttribute('aria-label',t('Tam ekranda incele','Inspect full screen'));on(el,'keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open(items,typeof index==='function'?index():index,el);}});}on(el,'click',e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();open(items,typeof index==='function'?index():index,el);});};
 document.querySelectorAll('.board-figure>a').forEach((a,i)=>bind(a,i+2));document.querySelectorAll('.case-hero img').forEach(el=>bind(el,0));document.querySelectorAll('.case-render img').forEach(el=>bind(el,1));document.querySelectorAll('.process-image').forEach(el=>bind(el,()=>+document.querySelector('.process-range').value));
 }else{const portrait=document.querySelector('.portrait-assembly');if(portrait){portrait.tabIndex=0;portrait.setAttribute('role','button');portrait.classList.add('viewer-trigger');portrait.setAttribute('aria-label',t('Eskizi tam ekranda incele','Inspect the sketch full screen'));const act=()=>open([{src:'assets/sketches/landscape-assembly.webp',label:t('Profil eskizi','Profile sketch')}],0,portrait);on(portrait,'click',act);on(portrait,'keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act();}});}}
 return ()=>{close();abort.abort();dialog.remove();};
}
